import numpy as np


def planted_partition(n, p_in, p_out, seed):
    g = np.random.default_rng(seed)
    y = (np.arange(n) >= n // 2).astype(int)
    A = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1, n):
            if g.random() < (p_in if y[i] == y[j] else p_out):
                A[i, j] = A[j, i] = 1.0
    return A, y

